import json

# Active admitted factors (audit cycle 3: kept=7, quarantined=[]) with validation metrics
factors = {
    "eurusd_beta_60d":     {"ic": -0.0551, "icir": -0.1563},
    "rate_beta_cn10y_60d": {"ic": -0.0520, "icir": -0.1543},
    "dn_mkt_beta_60d":     {"ic":  0.0554, "icir":  0.1404},
    "mom_120d_skip5":      {"ic":  0.0521, "icir":  0.1381},
    "mom_10d_skip5":       {"ic":  0.0409, "icir":  0.1183},
    "vix_beta_cond_60x20": {"ic": -0.0382, "icir": -0.0927},
    "vol_of_vol20x60":     {"ic":  0.0424, "icir":  0.1206},
}
# Crowding check from decoded artifacts: dn_mkt_beta_60d vs vol_of_vol20x60 rho=+0.562 (>0.5 threshold)
# -> cluster-prune lower-quality member (vol_of_vol20x60) to keep diversification.
DROP = {"vol_of_vol20x60"}
selected = {k: v for k, v in factors.items() if k not in DROP}

# quality_ic_tilt: q = |IC| * |ICIR|, direction = sign(IC)
qs = {fid: abs(m["ic"]) * abs(m["icir"]) for fid, m in selected.items()}
total = sum(qs.values())
ensemble = {
    "schema_version": 1,
    "selected_factors": [
        {
            "factor_id": fid,
            "weight": round(q / total, 3),
            "direction": 1 if selected[fid]["ic"] > 0 else -1,
        }
        for fid, q in sorted(qs.items(), key=lambda kv: -kv[1])
    ],
    "method": "quality_ic_tilt",
}
# Fix rounding so weights sum exactly to 1.0
wsum = sum(f["weight"] for f in ensemble["selected_factors"])
if abs(wsum - 1.0) > 1e-9:
    ensemble["selected_factors"][0]["weight"] = round(ensemble["selected_factors"][0]["weight"] + (1.0 - wsum), 3)

json.dump(ensemble, open("factors/factor_ensemble.json", "w"), indent=1)
print(json.dumps(ensemble, indent=1))
print("sum weights =", sum(f["weight"] for f in ensemble["selected_factors"]))
EOF

